import{_ as o,a0 as l,w as r,s as d,I as t,x as e,a1 as i,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"使用 Btrfs 快照进行增量备份 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Btrfs 快照进行增量备份 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Btrfs 快照进行增量备份 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Btrfs 快照进行增量备份 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200914 Incremental backups with Btrfs snapshots","title":"使用 Btrfs 快照进行增量备份","tag":"202009","desc":""},"relativePath":"202009/20200914 Incremental backups with Btrfs snapshots.md","filePath":"[post].md"}'),h={name:"202009/20200914 Incremental backups with Btrfs snapshots.md"};function u(b,s,f,k,m,g){const a=l("Link");return r(),d("div",null,[s[18]||(s[18]=t("h1",{id:"使用-btrfs-快照进行增量备份",tabindex:"-1"},[e("使用 Btrfs 快照进行增量备份 "),t("a",{class:"header-anchor",href:"#使用-btrfs-快照进行增量备份","aria-label":"Permalink to “使用 Btrfs 快照进行增量备份”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/26/112524cppfppjpvplyjzyx.jpg",alt:""})],-1)),s[20]||(s[20]=t("p",null,[t("ruby",null,[e("快照"),t("rt",null,"snapshot")]),e("是 Btrfs 的一个有趣的功能。快照是一个子卷的副本。生成快照是立即的。然而，生成快照与执行 "),t("code",null,"rsync"),e(" 或 "),t("code",null,"cp"),e(" 不同，快照并不是一创建就会占用空间。")],-1)),t("blockquote",null,[t("p",null,[s[1]||(s[1]=e("编者注：来自 ",-1)),i(a,{href:"https://btrfs.wiki.kernel.org/index.php/SysadminGuide#Snapshots"},{default:n(()=>[...s[0]||(s[0]=[e("BTRFS Wiki",-1)])]),_:1}),s[2]||(s[2]=e("：快照简单的来说就是一个子卷，它使用 Btrfs 的 COW 功能与其他子卷共享其数据（和元数据）。",-1))])]),s[21]||(s[21]=p(`<p>占用的空间将随着原始子卷或快照本身（如果它是可写的）的数据变化而增加。子卷中已添加/修改的文件和已删除的文件仍然存在于快照中。这是一种方便的备份方式。</p><h3 id="使用快照进行备份" tabindex="-1">使用快照进行备份 <a class="header-anchor" href="#使用快照进行备份" aria-label="Permalink to “使用快照进行备份”">​</a></h3><p>快照驻留在子卷所在的同一磁盘上。你可以像浏览普通目录一样浏览它，并按照生成快照时的状态恢复文件的副本。顺便说一下，在快照子卷的同一磁盘上生成快照并不是一个理想的备份策略：如果硬盘坏了，快照也会丢失。快照的一个有趣的功能是可以将快照发送到另一个位置。快照可以被发送到外部硬盘或通过 SSH 发送到远程系统（目标文件系统也需要格式化为 Btrfs）。要实现这个，需要使用命令 <code>btrfs send</code> 和 <code>btrfs receive</code>。</p><h3 id="生成快照" tabindex="-1">生成快照 <a class="header-anchor" href="#生成快照" aria-label="Permalink to “生成快照”">​</a></h3><p>要使用 <code>btrfs send</code> 和 <code>btrfs receive</code> 命令，重要的是要将快照创建为只读，而快照默认是可写的。</p><p>下面的命令将对 <code>/home</code> 子卷进行快照。请注意 <code>-r</code> 标志代表只读。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume snapshot -r /home /.snapshots/home-day1</span></span></code></pre></div><p>快照的名称可以是当前日期，而不是 <code>day1</code>，比如 <code>home-$(date +%Y%m%d)</code>。快照看起来像普通的子目录。你可以把它们放在任何你喜欢的地方。目录 <code>/.snapshots</code> 可能是一个不错的选择，以保持它们的整洁和避免混淆。</p><blockquote><p>编者注：快照不会对自己进行递归快照。如果你创建了一个子卷的快照，子卷所包含的每一个子卷或快照都会被映射到快照里面的一个同名的空目录。</p></blockquote><h3 id="使用-btrfs-send-进行备份" tabindex="-1">使用 btrfs send 进行备份 <a class="header-anchor" href="#使用-btrfs-send-进行备份" aria-label="Permalink to “使用 btrfs send 进行备份”">​</a></h3><p>在本例中，U 盘中的目标 Btrfs 卷被挂载为 <code>/run/media/user/mydisk/bk</code>。发送快照到目标卷的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs send /.snapshots/home-day1 | sudo btrfs receive /run/media/user/mydisk/bk</span></span></code></pre></div><p>这被称为初始启动，它相当于一个完整的备份。这个任务需要一些时间，取决于 <code>/home</code> 目录的大小。显然，后续的增量发送只需要更短的时间。</p><h3 id="增量备份" tabindex="-1">增量备份 <a class="header-anchor" href="#增量备份" aria-label="Permalink to “增量备份”">​</a></h3><p>快照的另一个有用的功能是能够以增量的方式执行发送任务。让我们再来生成一个快照。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume snapshot -r /home /.snapshots/home-day2</span></span></code></pre></div><p>为了执行增量发送任务，需要指定上一个快照作为基础，并且这个快照必须存在于源文件和目标文件中。请注意 <code>-p</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs send -p /.snapshot/home-day1 /.snapshot/home-day2 | sudo btrfs receive /run/media/user/mydisk/bk</span></span></code></pre></div><p>再来一次（一天之后）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume snapshot -r /home /.snapshots/home-day3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo btrfs send -p /.snapshot/home-day2 /.snapshot/home-day3 | sudo btrfs receive /run/media/user/mydisk/bk</span></span></code></pre></div><h3 id="清理" tabindex="-1">清理 <a class="header-anchor" href="#清理" aria-label="Permalink to “清理”">​</a></h3><p>操作完成后，你可以保留快照。但如果你每天都执行这些操作，你可能最终会有很多快照。这可能会导致混乱，并可能会在你的磁盘上使用大量的空间。因此，如果你认为你不再需要一些快照，删除它们是一个很好的建议。</p><p>请记住，为了执行增量发送，你至少需要最后一个快照。这个快照必须存在于源文件和目标文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo btrfs subvolume delete /.snapshot/home-day1</span></span>
<span class="line"><span>sudo btrfs subvolume delete /.snapshot/home-day2</span></span>
<span class="line"><span>sudo btrfs subvolume delete /run/media/user/mydisk/bk/home-day1</span></span>
<span class="line"><span>sudo btrfs subvolume delete /run/media/user/mydisk/bk/home-day2</span></span></code></pre></div><p>注意：第 3 天的快照被保存在源文件和目标文件中。这样，明天（第 4 天），你就可以执行新的增量 <code>btrfs send</code>。</p><p>最后的建议是，如果 U 盘的空间很大，可以考虑在目标盘中保留多个快照，而在源盘中只保留最后一个快照。</p><hr>`,27)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),i(a,{href:"https://fedoramagazine.org/btrfs-snapshots-backup-incremental/"},{default:n(()=>[...s[3]||(s[3]=[e("https://fedoramagazine.org/btrfs-snapshots-backup-incremental/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"https://fedoramagazine.org/author/alciregi/"},{default:n(()=>[...s[5]||(s[5]=[e("Alessio",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const C=o(h,[["render",u]]);export{v as __pageData,C as default};
